package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

@Service public class RefundParcelWorkspace {
    @Resource RefundService refunds;
    @Resource RefundParcelPolicy policy;
    @Resource RefundReturnClient returns;
    @Resource RefundGoodsService goods;
    @Resource RefundSharedScope scope;
    public Object list(String c,long refund){refunds.business(c,refund,false);List<Map<String,Object>> parcels=data(returns.parcels(c,refund,SecurityConstants.INNER));return parcels;}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> members(Map<String,Object> parcel){return (List<Map<String,Object>>)parcel.get("members");}
    public Object candidates(String c,long refund,String carrier,String waybill){refunds.business(c,refund,false);return data(returns.parcelCandidates(c,carrier.toUpperCase(Locale.ROOT).trim(),waybill.trim(),SecurityConstants.INNER));}
    public Object attach(String c,long refund,long plan,Map<String,Object> input,String actor){return attach(c,refund,plan,input,actor,false);}
    Object attach(String c,long refund,long plan,Map<String,Object> input,String actor,boolean automatic){return attach(c,refund,plan,input,actor,automatic,false);}
    Object attach(String c,long refund,long plan,Map<String,Object> input,String actor,boolean automatic,boolean late){String lease=token();Map<String,Object> command=refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,refund,true),p=refunds.platform(c,number(b,"platform_refund_id"),true);require("APPROVED".equals(text(b,"review_state"))&&number(b,"approved_version")==number(p,"version")&&!"CLOSED".equals(text(p,"platform_status"))&&(!"DONE".equals(text(b,"goods_state"))||refunds.repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=? AND gift_plan_id IS NOT NULL",Long.class,c,refund,plan)==1),"请先审核当前平台方案，已关闭或完成的退款不能新增包裹安排");require(number(input,"control_version")==number(b,"control_version"),"退款信息已变化，请刷新");List<Map<String,Object>> plans=refunds.repository.db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=? FOR UPDATE",ROW,c,refund,plan);require(plans.size()==1,"退回计划不属于本退款单");Map<String,Object> row=plans.get(0);require(number(row,"control_version")==number(input,"plan_version")&&!Arrays.asList("CLOSED","RELEASED","STOPPED").contains(text(row,"state")),"退回计划已变化或结束，请刷新");require(refunds.repository.db().update("UPDATE oms_refund_return_plan SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,plan)==1,"计划正在处理，请稍后重试");if(late){goods.verifyParcelScope(c,b,row);require("APPEND_AFTER_RECEIPT".equals(text(obj(row.get("parcel_issue")),"code"))&&number(obj(row.get("parcel_issue")),"target_parcel_id")==number(input,"join_parcel_id"),"请先核对本退款的目标包裹");}Map<String,Object> body=new LinkedHashMap<>(input);body.putAll(m("refund_id",refund,"refund_sn",b.get("refund_sn"),"order_sn",b.get("order_sn"),"source_line_id",row.get("shipment_line_id"),"sku_sn",row.get("sku_sn"),"quantity",row.get("quantity"),"store_code",row.get("result_json")==null?row.get("store_code"):obj(row.get("result_json")).get("store_code"),"actor",actor,"channel_id",b.get("channel_id"),"platform_tid",b.get("platform_tid"),"association_mode",automatic?"AUTO":"MANUAL","late_review",late,"request_json",obj(row.get("request_json")),"return_address",row.get("return_address"),"return_contact",row.get("return_contact"),"policy",policy.get(c,number(b,"channel_id"))));return body;});
        try{Object result=data(returns.attachParcel(c,plan,command,SecurityConstants.INNER));for(Map<String,Object> parcel:data(returns.parcels(c,refund,SecurityConstants.INNER))){Set<Long> ids=new HashSet<>();for(Map<String,Object> member:members(parcel))ids.add(number(member,"refund_id"));if(ids.size()>1)for(Long member:ids)refunds.repository.db().update("UPDATE oms_refund SET shared_return=1 WHERE company_code=? AND id=?",c,member);}refunds.repository.db().update("UPDATE oms_refund_return_plan SET parcel_state='LINKED',parcel_error='',parcel_issue=NULL,parcel_resolution=?,parcel_manual_dispatch=?,control_version=control_version+1 WHERE company_code=? AND id=?",late?"SUPPLEMENTED":automatic?"":"MANUAL_LINKED",late?1:0,c,plan);if(!automatic)refunds.repository.db().update("UPDATE oms_refund_return_plan SET return_carrier=?,return_waybill=?,logistics_source='MANUAL',transport_evidence=? WHERE company_code=? AND id=?",command.get("carrier_code"),command.get("waybill"),input.get("evidence"),c,plan);refunds.event(c,refund,"RETURN_PARCEL",(automatic?"自动":"人工")+"关联；退回计划 #"+plan+" 已关联退回包裹；同运单不合并退款，实收按商品来源处理；依据："+required(input,"reason",500)+"；凭证："+required(input,"evidence",1000),actor);return result;}finally{refunds.repository.db().update("UPDATE oms_refund_return_plan SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,plan,lease);}
    }
    Map<String,Object> dispatchScope(String c,long refund,long plan){return scope.validate(c,refund,plan,false);}
    Map<String,Object> dispatchScope(String c,long refund,long plan,boolean rebuild){return scope.validate(c,refund,plan,rebuild);}
    public Object documentAction(String c,long refund,long parcel,String action,Map<String,Object> input,String actor){
        List<Map<String,Object>> ps=data(returns.parcels(c,refund,SecurityConstants.INNER));Map<String,Object> p=ps.stream().filter(x->number(x,"id")==parcel).findFirst().orElseThrow(()->new IllegalArgumentException("包裹不属于本退款单"));require(number(input,"parcel_version")==number(p,"control_version"),"包裹范围变化，请刷新核对");require(Arrays.asList("dispatch","query","retry","posting","cancel","rebuild").contains(action),"共同THK操作无效");require(Boolean.TRUE.equals(input.get("confirmed_shared")),"请确认全部关联退款及共同THK处理范围");required(input,"reason",500);required(input,"evidence",1000);Map<String,Object> member=members(p).stream().filter(x->number(x,"refund_id")==refund).findFirst().get();long plan=number(member,"plan_id");Map<String,Object> body=new LinkedHashMap<>(input);body.put("actor",actor);
        if("dispatch".equals(action)){dispatchScope(c,refund,plan);Map<String,Object> command=refunds.repository.db().query("SELECT request_json FROM oms_refund_return_plan WHERE company_code=? AND id=?",ROW,c,plan).get(0);Map<String,Object> request=obj(command.get("request_json"));request.put("parcel_version",p.get("control_version"));data(returns.prepare(c,plan,request,SecurityConstants.INNER));}
        else{if("rebuild".equals(action)||"retry".equals(action))dispatchScope(c,refund,plan,"rebuild".equals(action));Map<String,Object> actual=data(returns.detail(c,plan,SecurityConstants.INNER));data(returns.document(c,plan,number(actual,"id"),action,body,SecurityConstants.INNER));}
        Set<Long> affected=new LinkedHashSet<>();for(Map<String,Object> m:members(p))affected.add(number(m,"refund_id"));for(Long memberRefund:affected){goods.refresh(c,memberRefund);refunds.event(c,memberRefund,"RETURN_SHARED_DOCUMENT","共同THK操作："+action+"；关联包裹 "+p.get("parcel_sn")+"?"+text(input,"reason"),actor);}return list(c,refund);
    }
    public Object transport(String c,long refund,long parcel,Map<String,Object> input,String actor){refunds.business(c,refund,false);Map<String,Object> body=new LinkedHashMap<>(input);body.put("actor",actor);Object result=data(returns.parcelTransport(c,refund,parcel,body,SecurityConstants.INNER));refunds.event(c,refund,"PARCEL_LOGISTICS","退回包裹 #"+parcel+" 更新物流信息；物流签收不代表仓库实收；"+text(input,"reason"),actor);return result;}
    public Object evaluateAutomatic(String c,long refund,long parcel,long event,Map<String,Object> input,String actor){refunds.business(c,refund,false);Map<String,Object> result=data(returns.evaluateAutomatic(c,refund,parcel,event,input,SecurityConstants.INNER));if(Boolean.TRUE.equals(input.get("execute"))){Set<Long> affected=new HashSet<>();for(Map<String,Object> row:(List<Map<String,Object>>)result.get("rows"))affected.add(number(row,"refund_id"));for(Long id:affected){goods.refresh(c,id);refunds.event(c,id,"AUTO_RECEIPT",text(result,"reason")+"；规则版本 "+result.get("policy_revision"),actor);}}return result;}
    public Object allocate(String c,long refund,long parcel,long event,Map<String,Object> input,String actor){refunds.business(c,refund,false);Map<String,Object> body=new LinkedHashMap<>(input);body.put("actor",actor);data(returns.allocateParcel(c,refund,parcel,event,body,SecurityConstants.INNER));refunds.event(c,refund,"PARCEL_RECEIPT","包裹 #"+parcel+" 回传 #"+event+" 已核对归属；"+text(input,"reason")+"；凭证："+text(input,"evidence"),actor);return list(c,refund);}
}
